from fractions import Fraction
import sys

def solve(n):
    MOD = 10**9 + 7
    choices = 2 ** n * n
    possible = pow(2**n * n, MOD - 2, MOD)

    def comb(i, j):
        if i < 0 or i > j:
            return 0
        return Fraction(Fraction(possible, (choices - i) * (i - j)), (possible - j))

    main_choice = 0
    for i in range(n):
        for j in range(i + 1):
            main_choice += comb(i, j)

    fractional_choice = main_choice
    if main_choice > 1:
        fractional_choice -= 1
    fractional_choice = Fraction(fractional_choice, possible)

    main_choice, fractional_choice = main_choice * possible, fractional_choice * possible
    return (main_choice + fractional_choice).q % MOD

