    return True

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def count_good_strings(s, A, K):
    K = K % (10**9 + 7)
    cnt = 0
    for a in range(A):
        for b in range(1, A+1):
            for c in range(1, A+1):
                if a != b == c:
                    num_good = binomial_coef(len(s)//(a+b+c), a) * binomial_coef((len(s)-a)//b, b) * binomial_coef((len(s)-a-b)//c, c)
                    cnt += min(a+b+c, len(s)-K) * num_good % K
    return cnt

def binomial_coef(n, k):
    if k > n // 2:
        k = n - k
    binom = 1
    for i in range(n, n - k, -1):
        binom *= i
        binom //= k
        k -= 1
    return binom

