def find_profile(n: int, mask: List[int]) -> List[int]:
    profile = [0] * n

    for i in range(n):
        profile[i] = mask[i]

    for i in range(n):
        if profile[i] == 0:
            for j in range(i + 1, n):
                if profile[j] > 0:
                    profile[i] = profile[j]
                    profile[j] = -1
                    break

    unique_profile = set()

    for i in range(n):
        if profile[i] != 0:
            unique_profile.add(profile[i])

    if len(unique_profile) == 1:
        return [profile[i] for i in range(n)]
    elif len(unique_profile) == 2:
        return sorted(list(unique_profile))
    else:
        return []

