@lru_cache(maxsize=None)
def choose(n, s, edges=None):
    if not edges:
        edges = [False] * (n + 1)
    if s == n:
        return 1
    ans = int(s == n - 1)
    for e in range(1, n + 1):
        if edges[e]:
            continue
        ans = ans * (s + e - 1) % MOD
        ans = ans * choose(n - e, s + e) % MOD
        edges[e] = True
    return ans

@lru_cache(maxsize=None)
def prob(test_case):
    # Calculate the probability using the comb functoin theory and memoization
    return (choose(n, 0) - 1) % MOD if test_case == 0 else choose(n, 0) % MOD

def solve(n):
    if n < 2:
        return 1

    binary_mod = 2**31
    prob_0 = prob(0)
    prob_1 = prob(1)

    # Calculate the target probability for each test case to bitwise considering the probabilities
    return (prob_1 - prob_0 + binary_mod) % binary_mod

