def max_greedy_subsequence_lengths(arr, k):
    n = len(arr)
    prefix_sums = [0]
    for num in arr:
        prefix_sums.append(prefix_sums[-1] + (num != prefix_sums[-1]))

    dp = [[-1 for _ in range(n + 1)] for _ in range(k + 1)]
