from math import gcd
from functools import reduce
from operator import mul
from typing import List

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def compute_lcm(a: int, b: int) -> int:
    if max(a, b) == 1:
        return max(a, b)
    elif max(a, b) == 2:
        return 1
    elif max(a, b) == 4:
        return 2
    else:
        lcm_val = a if b % a == 0 else b
        i = 2
        while i * i <= lcm_val:
            if lcm_val % i == 0:
                while (lcm_val % i == 0) and i > 1:
                    lcm_val /= i
            i += 1
        if lcm_val > 1:
            lcm_val *= i
        return lcm_val

def solve(arr: List[int], q: int) -> List[int]:
    n, m = len(arr), []
    mod = 10**9 + 7
    for i in range(m):
        l, r = (sum(arr) + i * 2) % n + 1, (sum(arr) + i * 2) % n + 1
        if l > r:
            l, r = r, l
        mul = reduce(lcm, arr[l:r], 1) % mod
        return [mul]

