def find_profile(mask):
    n = len(mask)
    profile_length = [0] * n
    is_consecutive = [False] * n
    is_valid = [False] * n

    for i in range(n):
        if mask[i] == '#':
            profile_length[i] = 1
            is_consecutive[i] = True
            is_valid[i] = True
        else:
            profile_length[i] = profile_length[i-1] + 1
            is_consecutive[i] = is_consecutive[i-1] or is_consecutive[i-1]
            is_valid[i] = profile_length[i] >= i+1

    dp = [0] * n
    updated = set()

    for i in range(n-1, -1, -1):
        if mask[i] == '#' and i == n-1:
            profile_length[i] = 1
            is_consecutive[i] = True
            is_valid[i] = True
        elif profile_length[i] > profile_length[i+1]:
            dp[i] = profile_length[i] + 1
        else:
            dp[i] = dp[i+1] + 1

        if mask[i] == '#' and not is_valid[i]:
            updated.remove(i)
        elif is_consecutive[i]:
            updated.add(i)
        else:
            updated.add(i)

    choice = updated.pop()
    for i in range(n-1, -1, -1):
        if mask[i] == '#' and profile_length[i] == dp[i]:
            is_consecutive[i] = True
            is_valid[i] = True
    profile_length[choice] = dp[choice]

    return profile_length

